/**
 * emit to subscription queries of type FindPurchaseOrder,
 * but only if the id matches
 *
 * @param		entity	PurchaseOrder
 */
	protected void emitFindPurchaseOrder( PurchaseOrder entity ) {
		LOGGER.info("handling emitFindPurchaseOrder" );
		
	    queryUpdateEmitter.emit(FindPurchaseOrderQuery.class,
	                            query -> query.getFilter().getPurchaseOrderId().equals(entity.getPurchaseOrderId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPurchaseOrder
	 * 
	 * @param		entity	PurchaseOrder
	 */
	protected void emitFindAllPurchaseOrder( PurchaseOrder entity ) {
		LOGGER.info("handling emitFindAllPurchaseOrder" );
		
	    queryUpdateEmitter.emit(FindAllPurchaseOrderQuery.class,
	                            query -> true,
	                            entity);
	}

